<?php
declare(strict_types=1);
require __DIR__ . '/db.php';
require __DIR__ . '/mailer.php';
require __DIR__ . '/telegram.php';
set_exception_handler(static function (Throwable $error): void {
    error_log('Tasks API error: ' . $error->getMessage());
    jsonResponse(false, 'Помилка задачі: ' . $error->getMessage(), [], 500);
});
session_start();
if (empty($_SESSION['user_id'])) jsonResponse(false, 'Потрібна авторизація.', [], 401);
$pdo = db(); $userId = (string)$_SESSION['user_id']; $method = $_SERVER['REQUEST_METHOD'] ?? 'GET'; $data = $method === 'POST' ? body() : []; $action = (string)($data['action'] ?? '');
$columnsQuery = $pdo->prepare("SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'tasks' AND COLUMN_NAME IN ('recurrence_rule', 'recurrence_parent_id')");
$columnsQuery->execute(); $existingColumns = array_column($columnsQuery->fetchAll(), 'COLUMN_NAME');
if (!in_array('recurrence_rule', $existingColumns, true)) $pdo->exec("ALTER TABLE tasks ADD recurrence_rule VARCHAR(20) NOT NULL DEFAULT 'none'");
if (!in_array('recurrence_parent_id', $existingColumns, true)) $pdo->exec("ALTER TABLE tasks ADD recurrence_parent_id CHAR(32) NULL");
$pdo->exec("CREATE TABLE IF NOT EXISTS task_clients (task_id CHAR(32) NOT NULL, client_id CHAR(32) NOT NULL, PRIMARY KEY (task_id, client_id), INDEX idx_task_clients_client (client_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$userQuery = $pdo->prepare('SELECT id, name, email, role, avatar_url FROM users WHERE id = ? LIMIT 1'); $userQuery->execute([$userId]); $user = $userQuery->fetch(); $userQuery->closeCursor();
if (!$user) jsonResponse(false, 'Користувача не знайдено.', [], 401);
$isAdmin = in_array($user['role'], ['admin', 'owner'], true);
$canManage = in_array($user['role'], ['admin', 'owner', 'manager'], true);
function taskAccessSql(array $user, string $userId): array { if (in_array($user['role'], ['admin', 'owner'], true)) return ['', []]; return [' AND (t.created_by = ? OR t.assignee_id = ? OR EXISTS (SELECT 1 FROM task_assignees ta0 WHERE ta0.task_id = t.id AND ta0.user_id = ?))', [$userId, $userId, $userId]]; }
function idList($value): array { $values = is_array($value) ? $value : ($value === null || $value === '' ? [] : [$value]); return array_values(array_unique(array_filter(array_map(static fn($item): string => trim((string)$item), $values)))); }
function taskSelect(string $where = '1=1'): string { return "SELECT t.*, GROUP_CONCAT(DISTINCT tp.project_id) AS project_ids, GROUP_CONCAT(DISTINCT p.name SEPARATOR ', ') AS project_names, GROUP_CONCAT(DISTINCT ta.user_id) AS assignee_ids, GROUP_CONCAT(DISTINCT a.name SEPARATOR ', ') AS assignee_names, GROUP_CONCAT(DISTINCT tc.client_id) AS client_ids, GROUP_CONCAT(DISTINCT cl.name SEPARATOR ', ') AS client_names, p0.name AS primary_project_name, a0.name AS primary_assignee_name, c.name AS creator_name FROM tasks t LEFT JOIN task_projects tp ON tp.task_id = t.id LEFT JOIN projects p ON p.id = tp.project_id LEFT JOIN task_assignees ta ON ta.task_id = t.id LEFT JOIN users a ON a.id = ta.user_id LEFT JOIN task_clients tc ON tc.task_id = t.id LEFT JOIN clients cl ON cl.id = tc.client_id LEFT JOIN projects p0 ON p0.id = t.project_id LEFT JOIN users a0 ON a0.id = t.assignee_id JOIN users c ON c.id = t.created_by WHERE {$where} GROUP BY t.id"; }
function normalizeTask(array $task): array { $task['project_ids'] = $task['project_ids'] ? explode(',', $task['project_ids']) : ($task['project_id'] ? [$task['project_id']] : []); $task['assignee_ids'] = $task['assignee_ids'] ? explode(',', $task['assignee_ids']) : ($task['assignee_id'] ? [$task['assignee_id']] : []); $task['client_ids'] = $task['client_ids'] ? explode(',', $task['client_ids']) : []; $task['project_name'] = $task['project_names'] ?: $task['primary_project_name']; $task['assignee_name'] = $task['assignee_names'] ?: $task['primary_assignee_name']; return $task; }
function canAccessTask(PDO $pdo, array $user, string $userId, string $taskId): bool { [$sql, $params] = taskAccessSql($user, $userId); $query = $pdo->prepare("SELECT t.id FROM tasks t WHERE t.id = ? {$sql} LIMIT 1"); $query->execute(array_merge([$taskId], $params)); $allowed = (bool)$query->fetch(); $query->closeCursor(); return $allowed; }
function addHistory(PDO $pdo, string $taskId, string $userId, string $action, string $message): void { $pdo->prepare('INSERT INTO task_history (id, task_id, user_id, action, message) VALUES (?, ?, ?, ?, ?)')->execute([bin2hex(random_bytes(16)), $taskId, $userId, $action, $message]); }
function historyValue($value): string { $value = trim(preg_replace('/\s+/', ' ', strip_tags((string)$value))); if ($value === '') return 'не вказано'; return mb_strlen($value) > 160 ? mb_substr($value, 0, 160) . '…' : $value; }
function historyDescriptionChange(string $old, string $new): string { $oldText = historyValue($old); $newText = historyValue($new); preg_match_all('/<img\b/i', $old, $oldMatches); preg_match_all('/<img\b/i', $new, $newMatches); $oldImages = count($oldMatches[0]); $newImages = count($newMatches[0]); if ($oldText === $newText && $oldImages === $newImages) return ''; $images = $oldImages !== $newImages ? "; зображення: {$oldImages} → {$newImages}" : ''; return "опис: «{$oldText}» → «{$newText}»{$images}"; }
function taskReviewEmailHtml(string $title, string $message, string $taskUrl): string { $safeTitle = htmlspecialchars($title, ENT_QUOTES, 'UTF-8'); $safeMessage = htmlspecialchars($message, ENT_QUOTES, 'UTF-8'); $safeUrl = htmlspecialchars($taskUrl, ENT_QUOTES, 'UTF-8'); return '<!doctype html><html lang="uk"><body style="margin:0;padding:0;background:#f3f8f5;font-family:Arial,Helvetica,sans-serif;color:#17201e"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f3f8f5;padding:32px 12px"><tr><td align="center"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:600px;background:#ffffff;border:1px solid #dfeae3;border-radius:18px;overflow:hidden"><tr><td style="background:#1f8a68;padding:24px 30px"><div style="font-size:19px;font-weight:700;letter-spacing:1px;color:#ffffff">NEXAFLOW</div><div style="margin-top:5px;font-size:11px;letter-spacing:1.5px;color:#dff2e8">SRM SYSTEM</div></td></tr><tr><td style="padding:34px 30px 30px"><div style="display:inline-block;padding:7px 11px;border-radius:999px;background:#e8f5ed;color:#1f8a68;font-size:11px;font-weight:700;letter-spacing:.5px">ПОТРІБНА ДІЯ</div><h1 style="margin:18px 0 10px;font-size:25px;line-height:1.25;color:#17201e">Потрібна перевірка задачі</h1><p style="margin:0;color:#687a70;font-size:15px;line-height:1.6">' . $safeMessage . '</p><div style="margin:24px 0;padding:18px 20px;border-left:4px solid #1f8a68;border-radius:10px;background:#f4faf6"><div style="font-size:11px;color:#7b8983;text-transform:uppercase;letter-spacing:1px">Задача</div><div style="margin-top:7px;font-size:17px;font-weight:700;color:#17201e">' . $safeTitle . '</div></div><table role="presentation" cellspacing="0" cellpadding="0"><tr><td style="border-radius:9px;background:#1f8a68"><a href="' . $safeUrl . '" style="display:inline-block;padding:13px 20px;color:#ffffff;text-decoration:none;font-size:14px;font-weight:700">Переглянути задачу&nbsp; →</a></td></tr></table><p style="margin:26px 0 0;color:#91a099;font-size:12px;line-height:1.5">Перевірте результат і підтвердьте виконання або поверніть задачу на доопрацювання.</p></td></tr><tr><td style="padding:18px 30px;background:#f8fbf9;border-top:1px solid #e6eee9;color:#91a099;font-size:11px">Це автоматичне повідомлення від NexaFlow. Будь ласка, не відповідайте на цей лист.</td></tr></table></td></tr></table></body></html>'; }
function taskStatusEmailHtml(string $title, string $message, string $taskUrl): string { $safeTitle = htmlspecialchars($title, ENT_QUOTES, 'UTF-8'); $safeMessage = htmlspecialchars($message, ENT_QUOTES, 'UTF-8'); $safeUrl = htmlspecialchars($taskUrl, ENT_QUOTES, 'UTF-8'); return '<!doctype html><html lang="uk"><body style="margin:0;padding:32px 12px;background:#f3f8f5;font-family:Arial,sans-serif;color:#17201e"><table role="presentation" width="100%"><tr><td align="center"><table role="presentation" width="100%" style="max-width:600px;background:#fff;border:1px solid #dfeae3;border-radius:18px;overflow:hidden"><tr><td style="background:#1f8a68;padding:24px 30px;color:#fff;font-size:19px;font-weight:700">NEXAFLOW <span style="font-size:11px;font-weight:400">• SRM SYSTEM</span></td></tr><tr><td style="padding:30px"><div style="color:#1f8a68;font-size:12px;font-weight:700;letter-spacing:1px">ОНОВЛЕННЯ ЗАДАЧІ</div><h1 style="font-size:25px;margin:14px 0 10px">Задачу повернуто в роботу</h1><p style="font-size:15px;line-height:1.6;color:#687a70">' . $safeMessage . '</p><div style="margin:22px 0;padding:18px 20px;background:#f4faf6;border-left:4px solid #1f8a68;border-radius:10px"><div style="font-size:11px;color:#7b8983;text-transform:uppercase">Задача</div><div style="margin-top:7px;font-size:17px;font-weight:700">' . $safeTitle . '</div></div><a href="' . $safeUrl . '" style="display:inline-block;padding:13px 20px;background:#1f8a68;color:#fff;border-radius:9px;text-decoration:none;font-weight:700">Відкрити задачу →</a></td></tr><tr><td style="padding:18px 30px;background:#f8fbf9;color:#91a099;font-size:11px">Це автоматичне повідомлення від NexaFlow.</td></tr></table></td></tr></table></body></html>'; }
function notifyTaskManagers(PDO $pdo, string $taskId, string $actorId, string $title): void { $query = $pdo->prepare("SELECT DISTINCT u.id, u.name, u.email FROM users u WHERE u.id <> ? AND (EXISTS (SELECT 1 FROM tasks t0 LEFT JOIN task_projects tp ON tp.task_id = t0.id JOIN projects p ON p.id = COALESCE(tp.project_id, t0.project_id) LEFT JOIN project_members pm ON pm.project_id = p.id AND pm.user_id = u.id WHERE t0.id = ? AND (u.role IN ('admin', 'owner', 'manager') OR p.owner_id = u.id OR pm.role IN ('admin', 'manager'))) OR (NOT EXISTS (SELECT 1 FROM task_projects tp0 WHERE tp0.task_id = ?) AND u.id = (SELECT t.created_by FROM tasks t WHERE t.id = ?)))"); $query->execute([$actorId, $taskId, $taskId, $taskId]); $insert = $pdo->prepare("INSERT INTO notifications (id, user_id, sender_id, type, title, message, entity_type, entity_id) VALUES (?, ?, ?, 'task_review', ?, ?, 'task', ?)"); $recent = $pdo->prepare("SELECT id FROM notifications WHERE user_id = ? AND type = 'task_review' AND entity_type = 'task' AND entity_id = ? AND created_at >= DATE_SUB(NOW(), INTERVAL 3 SECOND) LIMIT 1"); foreach ($query->fetchAll() as $manager) { $recent->execute([$manager['id'], $taskId]); if ($recent->fetchColumn()) continue; $message = "Задача «{$title}» очікує вашої перевірки."; $insert->execute([bin2hex(random_bytes(16)), $manager['id'], $actorId, 'Потрібна перевірка задачі', $message, $taskId]); $taskUrl = 'https://nexaflow.top/tasks/' . rawurlencode($taskId); sendTelegramTaskReview($pdo, (string)$manager['id'], $title, $taskUrl); $html = taskReviewEmailHtml($title, $message, $taskUrl); sendProjectEmail((string)$manager['email'], 'Потрібна перевірка задачі — NexaFlow', $message . "\n\nПереглянути задачу: " . $taskUrl, $html); } }
function notifyTaskAssignees(PDO $pdo, string $taskId, string $actorId, string $title, string $type, string $notificationTitle, string $message): void { $query = $pdo->prepare("SELECT DISTINCT u.id, u.email FROM users u WHERE u.id <> ? AND (u.id = (SELECT t.created_by FROM tasks t WHERE t.id = ?) OR u.id = (SELECT t.assignee_id FROM tasks t WHERE t.id = ?) OR EXISTS (SELECT 1 FROM task_assignees ta WHERE ta.task_id = ? AND ta.user_id = u.id))"); $query->execute([$actorId, $taskId, $taskId, $taskId]); $insert = $pdo->prepare("INSERT INTO notifications (id, user_id, sender_id, type, title, message, entity_type, entity_id) VALUES (?, ?, ?, ?, ?, ?, 'task', ?)"); foreach ($query->fetchAll() as $recipient) { $insert->execute([bin2hex(random_bytes(16)), $recipient['id'], $actorId, $type, $notificationTitle, $message, $taskId]); $taskUrl = 'https://nexaflow.top/tasks/' . rawurlencode($taskId); sendTelegramTaskStatus($pdo, (string)$recipient['id'], $title, $message, $taskUrl, $type); sendProjectEmail((string)$recipient['email'], $notificationTitle . ' — NexaFlow', $message . "\n\nВідкрити задачу: " . $taskUrl, taskStatusEmailHtml($title, $message, $taskUrl)); } }
function createNextRecurringTask(PDO $pdo, string $sourceId, string $actorId): void { $query = $pdo->prepare("SELECT * FROM tasks WHERE id = ? AND recurrence_rule <> 'none' AND due_date IS NOT NULL LIMIT 1"); $query->execute([$sourceId]); $source = $query->fetch(); $query->closeCursor(); if (!$source) return; $nextDate = new DateTime((string)$source['due_date']); $nextDate->modify(['hourly' => '+1 hour', 'daily' => '+1 day', 'weekly' => '+1 week', 'monthly' => '+1 month', 'quarterly' => '+3 months', 'yearly' => '+1 year'][$source['recurrence_rule']] ?? '+1 month'); $duplicate = $pdo->prepare('SELECT id FROM tasks WHERE recurrence_parent_id = ? LIMIT 1'); $duplicate->execute([$sourceId]); $duplicateId = $duplicate->fetchColumn(); $duplicate->closeCursor(); if ($duplicateId) return; $nextId = bin2hex(random_bytes(16)); $pdo->prepare('INSERT INTO tasks (id, title, description, client_name, project_id, assignee_id, created_by, status, priority, due_date, reminder_at, creator_reminder, recurrence_rule, recurrence_parent_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')->execute([$nextId, $source['title'], $source['description'], $source['client_name'], $source['project_id'], $source['assignee_id'], $source['created_by'], 'todo', $source['priority'], $nextDate->format('Y-m-d'), null, $source['creator_reminder'], $source['recurrence_rule'], $sourceId]); $pdo->prepare('INSERT IGNORE INTO task_projects (task_id, project_id) SELECT ?, project_id FROM task_projects WHERE task_id = ?')->execute([$nextId, $sourceId]); $pdo->prepare('INSERT IGNORE INTO task_assignees (task_id, user_id) SELECT ?, user_id FROM task_assignees WHERE task_id = ?')->execute([$nextId, $sourceId]); addHistory($pdo, $nextId, $actorId, 'recurring_created', 'Автоматично створено з повторюваної задачі.'); }

if ($method === 'GET') {
    [$accessSql, $accessParams] = taskAccessSql($user, $userId); $detailId = trim((string)($_GET['id'] ?? ''));
    if ($detailId !== '') {
        $query = $pdo->prepare(taskSelect("t.id = ? {$accessSql}")); $query->execute(array_merge([$detailId], $accessParams)); $task = $query->fetch(); $query->closeCursor(); if (!$task) jsonResponse(false, 'Задачу не знайдено або у вас немає доступу.', [], 404); $task = normalizeTask($task);
        $history = $pdo->prepare('SELECT h.id, h.user_id, h.action, h.message, h.created_at, u.name AS user_name FROM task_history h LEFT JOIN users u ON u.id = h.user_id WHERE h.task_id = ? ORDER BY h.created_at DESC'); $history->execute([$detailId]); $attachments = $pdo->prepare('SELECT id, file_name, file_url, mime_type, created_at FROM task_attachments WHERE task_id = ? ORDER BY created_at DESC'); $attachments->execute([$detailId]); $timeEntries = $pdo->prepare('SELECT te.id, te.user_id, te.minutes, te.note, te.logged_at, u.name AS user_name FROM time_entries te JOIN users u ON u.id = te.user_id WHERE te.task_id = ? ORDER BY te.logged_at DESC'); $timeEntries->execute([$detailId]); $timeRows = $timeEntries->fetchAll(); $totalMinutes = array_sum(array_map(static fn(array $row): int => (int)$row['minutes'], $timeRows));
        jsonResponse(true, 'Задачу завантажено.', ['user' => $user, 'task' => $task, 'history' => $history->fetchAll(), 'attachments' => $attachments->fetchAll(), 'time_entries' => $timeRows, 'total_minutes' => $totalMinutes]);
    }
    $query = $pdo->prepare(taskSelect("1=1 {$accessSql}") . ' ORDER BY t.due_date IS NULL, t.due_date, t.created_at DESC'); $query->execute($accessParams); $tasks = array_map('normalizeTask', $query->fetchAll());
    if ($isAdmin) { $projectQuery = $pdo->query('SELECT id, name FROM projects ORDER BY name'); $peopleQuery = $pdo->query('SELECT id, name, email FROM users ORDER BY name'); } else { $projectQuery = $pdo->prepare("SELECT DISTINCT p.id, p.name FROM projects p LEFT JOIN project_members pm ON pm.project_id = p.id AND pm.user_id = ? WHERE p.owner_id = ? OR (p.visibility = 'team' AND pm.user_id = ?) ORDER BY p.name"); $projectQuery->execute([$userId, $userId, $userId]); $peopleQuery = $pdo->prepare("SELECT DISTINCT u.id, u.name, u.email FROM users u WHERE u.id = ? OR EXISTS (SELECT 1 FROM project_members pm JOIN projects p ON p.id = pm.project_id WHERE pm.user_id = u.id AND (p.owner_id = ? OR (p.visibility = 'team' AND EXISTS (SELECT 1 FROM project_members pm2 WHERE pm2.project_id = p.id AND pm2.user_id = ?)))) ORDER BY u.name"); $peopleQuery->execute([$userId, $userId, $userId]); }
    jsonResponse(true, 'Задачі завантажено.', ['user' => $user, 'tasks' => $tasks, 'projects' => $projectQuery->fetchAll(), 'people' => $peopleQuery->fetchAll(), 'permissions' => ['create' => true, 'admin' => $isAdmin]]);
}
if ($method !== 'POST') jsonResponse(false, 'Метод не підтримується.', [], 405);
if ($action === 'add_history') { $taskId = trim((string)($data['id'] ?? '')); $message = trim((string)($data['message'] ?? '')); if (!$taskId || !$message) jsonResponse(false, 'Дані історії неповні.', [], 422); if (!canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); addHistory($pdo, $taskId, $userId, 'description_detail', $message); jsonResponse(true, 'Дію додано в історію.'); }
if ($action === 'set_reminder') { $taskId = trim((string)($data['task_id'] ?? '')); $reminderAt = trim((string)($data['reminder_at'] ?? '')) ?: null; if (!$taskId || !canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); if ($reminderAt !== null) { $date = DateTime::createFromFormat('Y-m-d\TH:i', $reminderAt); if (!$date || $date->format('Y-m-d\TH:i') !== $reminderAt) jsonResponse(false, 'Вкажіть коректну дату та час.', [], 422); } $pdo->prepare('UPDATE tasks SET reminder_at = ? WHERE id = ?')->execute([$reminderAt, $taskId]); if ($reminderAt) addHistory($pdo, $taskId, $userId, 'reminder_updated', 'Нагадування перенесено на ' . $date->format('d.m.Y H:i') . '.'); else addHistory($pdo, $taskId, $userId, 'reminder_removed', 'Нагадування вимкнено.'); jsonResponse(true, $reminderAt ? 'Нове нагадування встановлено.' : 'Нагадування вимкнено.'); }
if ($action === 'log_time') { $taskId = trim((string)($data['task_id'] ?? '')); $minutes = (int)($data['minutes'] ?? 0); $note = trim((string)($data['note'] ?? '')) ?: null; if (!$taskId || $minutes < 1 || $minutes > 1440) jsonResponse(false, 'Вкажіть час від 1 до 1440 хвилин.', [], 422); if (!canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); $pdo->prepare('INSERT INTO time_entries (id, task_id, user_id, minutes, note) VALUES (?, ?, ?, ?, ?)')->execute([bin2hex(random_bytes(16)), $taskId, $userId, $minutes, $note]); $hours = intdiv($minutes, 60); $rest = $minutes % 60; $timeLabel = $hours ? "{$hours} год " . ($rest ? "{$rest} хв" : '') : "{$rest} хв"; addHistory($pdo, $taskId, $userId, 'time_logged', "Додано {$timeLabel} роботи" . ($note ? " ({$note})" : '') . '.'); jsonResponse(true, 'Час додано до задачі.'); }
if ($action === 'add_attachment') { $taskId = trim((string)($data['task_id'] ?? '')); $url = trim((string)($data['file_url'] ?? '')); $fileName = trim((string)($data['file_name'] ?? 'Зображення')); if (!$taskId || !$url || !filter_var($url, FILTER_VALIDATE_URL)) jsonResponse(false, 'Вкажіть коректне посилання на зображення.', [], 422); if (!canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); $pdo->prepare('INSERT INTO task_attachments (id, task_id, user_id, file_name, file_url, mime_type) VALUES (?, ?, ?, ?, ?, ?)')->execute([bin2hex(random_bytes(16)), $taskId, $userId, $fileName, $url, 'image/*']); addHistory($pdo, $taskId, $userId, 'attachment_added', "Додано зображення «{$fileName}»."); jsonResponse(true, 'Зображення додано.'); }
if ($action === 'set_status') { $taskId = trim((string)($data['id'] ?? '')); $newStatus = trim((string)($data['status'] ?? '')); $allowedStatuses = ['todo', 'in_progress', 'review', 'done', 'cancelled', 'archived']; if (!$taskId || !in_array($newStatus, $allowedStatuses, true)) jsonResponse(false, 'Некоректний статус задачі.', [], 422); if (!canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); $oldQuery = $pdo->prepare('SELECT status, title FROM tasks WHERE id = ?'); $oldQuery->execute([$taskId]); $taskRow = $oldQuery->fetch(); $oldStatus = (string)($taskRow['status'] ?? 'todo'); $isManager = in_array($user['role'], ['admin', 'owner', 'manager'], true); if (!$isManager && in_array($newStatus, ['cancelled', 'archived'], true)) jsonResponse(false, 'Скасувати або архівувати задачу може лише менеджер чи адміністратор.', [], 403); if (!$isManager && $newStatus === 'done') $newStatus = 'review'; $pdo->prepare('UPDATE tasks SET status = ? WHERE id = ?')->execute([$newStatus, $taskId]); if ($oldStatus !== $newStatus) addHistory($pdo, $taskId, $userId, 'status_updated', 'Статус: «' . $oldStatus . '» → «' . $newStatus . '».'); if (!$isManager && $newStatus === 'review' && $oldStatus !== 'review') notifyTaskManagers($pdo, $taskId, $userId, (string)$taskRow['title']); if ($isManager && $oldStatus === 'review' && $newStatus === 'done') { addHistory($pdo, $taskId, $userId, 'review_approved', 'Менеджер підтвердив виконання задачі.'); notifyTaskAssignees($pdo, $taskId, $userId, (string)$taskRow['title'], 'task_review_approved', 'Задачу підтверджено', "Менеджер підтвердив виконання задачі «{$taskRow['title']}»."); } if ($isManager && $oldStatus === 'review' && $newStatus === 'in_progress') { addHistory($pdo, $taskId, $userId, 'review_rejected', 'Менеджер повернув задачу на доопрацювання.'); notifyTaskAssignees($pdo, $taskId, $userId, (string)$taskRow['title'], 'task_review_rejected', 'Задачу повернуто на доопрацювання', "Менеджер по